@push('scripts')<script>$(function(){var $t=$('#clearing-table'),x=$.fn.dataTable.render.text(),labels={DRAFT:'ร่าง',SUBMITTED:'รออนุมัติ',APPROVED:'อนุมัติแล้ว',POSTED:'ลงบัญชีแล้ว',REVERSED:'ยกเลิกรายการแล้ว',VOID:'ยกเลิก'},classes={DRAFT:'app-status-neutral',SUBMITTED:'app-status-info',APPROVED:'app-status-success',POSTED:'app-status-success',REVERSED:'app-status-danger',VOID:'app-status-danger'};var table=$t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:$t.data('url'),data:function(d){d.status=$('#clearing-status').val();d.petty_cash_fund_id=$('#clearing-fund').val();}},order:[[0,'desc']],buttons:[window.erpExcelButton($t)],columns:[{data:'document_number',render:x.display},{data:'clearing_date_label',render:x.display},{data:'fund_label',render:x.display},{data:'expected_amount',className:'text-end',render:$.fn.dataTable.render.number(',','.',2)},{data:'actual_amount',className:'text-end',render:$.fn.dataTable.render.number(',','.',2)},{data:'variance_amount',className:'text-end',render:$.fn.dataTable.render.number(',','.',2)},{data:'status',render:function(v,t){return t==='display'?'<span class="badge '+(classes[v]||'app-status-neutral')+'">'+x.display(labels[v]||v)+'</span>':v;}},{data:null,orderable:false,searchable:false,className:'text-end',render:function(_,t,r){if(t!=='display')return '';var a='<a class="btn btn-sm btn-app-soft" href="'+x.display(r.show_url)+'"><i class="bx bx-show"></i></a>';if(r.edit_url)a+=' <a class="btn btn-sm btn-app-soft" href="'+x.display(r.edit_url)+'"><i class="bx bx-edit"></i></a>';return a;}}]}));$('#clearing-status,#clearing-fund').on('change',function(){table.ajax.reload();});$('#clearing-reset').on('click',function(){$('#clearing-status,#clearing-fund').val('');table.ajax.reload();});});</script>@endpush
